<!-- ACTIVATION SCRIPT: SIDEBAR STATE ACCORDING TO USER PROMPT -->
<script>
    (function() {
      // Activar la pestaña Cuentas Bancarias en la barra lateral global
      const navLinks = document.querySelectorAll('aside nav a');
      navLinks.forEach(link => {
        if (link.getAttribute('data-path') === 'cuentas-bancarias') {
          link.className = "flex items-center gap-space-sm px-space-md py-space-sm rounded-xl bg-primary text-on-primary font-label-lg rounded-xl shadow-[0_4px_12px_rgba(0,105,72,0.25)] transition-all";
          const icon = link.querySelector('.material-symbols-outlined');
          if (icon) icon.style.fontVariationSettings = "'FILL' 1";
        } else {
          link.className = "flex items-center gap-space-sm px-space-md py-space-sm rounded-xl text-on-surface-variant hover:bg-surface-container-high hover:text-on-surface transition-all";
          const icon = link.querySelector('.material-symbols-outlined');
          if (icon) icon.style.fontVariationSettings = "'FILL' 0";
        }
      });
    })();
